import sources from "../sources.json" with { type: "json" };
import { playback, rightsLine } from "../public/play.js";

/**
 * @param {Array<{ id: string, name: string, number: number, tagline: string, items: any[] }>} channels
 */
export function renderResources(channels) {
  const ordered = [...channels].sort((a, b) => a.number - b.number);
  const lines = [
    "# Plebflix TV tape library",
    "",
    "The channel JSON files in `channels/` are the source of truth. This page is generated by `npm run resources`. Do not edit it by hand.",
    "",
    "Plebflix does not host the video. Each tape plays from an embed of a YouTube upload (preferably the creator's or an official channel's) or, failing that, an archive.org embed. If neither exists, the glass shows a link to the original page. `original_url` is that page, or a Wayback snapshot when it is gone. What counts as a classic is in `CLASSIC.md`. A still with no embed is a link-out, not a file we render.",
    "",
    "A `pending` row was filed from the REC button. It is not in the live loop until someone confirms the embed, sets `duration` in seconds, and removes `\"status\": \"pending\"`.",
    "",
  ];

  for (const channel of ordered) {
    lines.push(`## ${channel.number}. ${channel.name}`, "", channel.tagline, "");
    lines.push(
      "| Title | Year | Signals | Why | Duration | Uploader | Play |",
      "| --- | ---: | --- | --- | ---: | --- | --- |",
    );
    const live = channel.items.filter((item) => item.status !== "pending");
    const pending = channel.items.filter((item) => item.status === "pending");
    for (const item of live) lines.push(row(item));
    lines.push("");
    if (pending.length) {
      lines.push(`### ${channel.name} — waiting on the deck`, "");
      lines.push(
        "| Title | Year | Signals | Why | Source |",
        "| --- | ---: | --- | --- | --- |",
      );
      for (const item of pending) {
        lines.push(
          `| ${cell(item.title)} | ${item.year} | ${cell((item.signals || []).join(""))} | ${cell(item.why || "")} | ${link(item)} |`,
        );
      }
      lines.push("");
    }
  }

  lines.push(
    "## Filing a tape",
    "",
    "Press REC on the deck, or edit `channels/suomi.json` / `channels/international.json` and open a pull request. The year has to be at least ten years ago, and at least three of the five signals in `CLASSIC.md` have to be honest. Run `npm run validate` and `npm run resources` before you push. `npm run check-embeds` (weekly) checks that YouTube ids still resolve and archive.org items still exist.",
    "",
    "## Shelves",
    "",
    "Places to look, and links the REC button will accept. A page from one of these shelves is not automatically a video. Playback still has to be an embed inside the set.",
    "",
  );
  for (const shelf of sources.shelves) {
    lines.push(`- [${cell(shelf.name)}](${shelf.url}) — ${cell(shelf.about)}`);
    for (const extra of shelf.links || []) {
      lines.push(`  - [${cell(extra.label)}](${extra.url})`);
    }
  }
  lines.push("", "## Finds", "");
  for (const find of sources.finds) {
    lines.push(`- [${cell(find.title)}](${find.url}) — ${cell(find.note)}`);
  }
  lines.push("");
  return lines.join("\n");
}

/** @param {any} item */
function row(item) {
  const signals = Array.isArray(item.signals) ? item.signals.join("") : "";
  const play = playback(item);
  return `| ${cell(item.title)} | ${item.year} | ${cell(signals)} | ${cell(item.why || item.note || "")} | ${formatDuration(item.duration)} | ${cell(play.uploader || "")} | ${playCell(item)} |`;
}

/** @param {string} value */
function cell(value) {
  return String(value).replace(/\|/g, "\\|").replace(/\n/g, " ");
}

/** @param {any} item */
function playCell(item) {
  const play = playback(item);
  const mark = play.official ? "official" : "not official";
  const credit = cell(rightsLine(item));
  if (play.kind === "youtube") return `[YouTube, ${mark}](https://www.youtube.com/watch?v=${play.id}) — ${credit}`;
  if (play.kind === "archive") return `[archive.org, ${mark}](https://archive.org/details/${encodeURIComponent(play.id)}) — ${credit}`;
  const url = play.id || item.original_url || "";
  return url ? `[link only](${url}) — ${credit}` : credit;
}

/** @param {any} item */
function link(item) {
  const url =
    item.original_url ||
    item.credit ||
    (item.source === "youtube" ? `https://www.youtube.com/watch?v=${item.embedId}` : "") ||
    (item.source === "archive.org" ? `https://archive.org/details/${item.embedId}` : "") ||
    (item.source === "vimeo" ? `https://vimeo.com/${item.embedId}` : "");
  return url ? `[source](${url})` : "";
}

/** @param {number} seconds */
function formatDuration(seconds) {
  const min = Math.floor(seconds / 60);
  const sec = seconds % 60;
  return `${min}:${String(sec).padStart(2, "0")}`;
}
